<?php
declare(strict_types=1);
require __DIR__ . '/../../../../lib/app.php';
require_once __DIR__ . '/../../home/php/neuria_cliente.php';
require_once __DIR__ . '/../../home/php/neuria_sanitizador.php';
app_require_mode([0,1,2]);
$db=app_db();$id=app_int('id');$neuriaId=app_int('neuria_id');$record=$id?$db->one('SELECT * FROM noticias WHERE id=?','i',[$id]):null;$isOffer=false;
if($id&&!$record){http_response_code(404);exit('Noticia inexistente.');}
if(!$id&&$neuriaId){$response=(new NeuriaCliente())->obtener($neuriaId);if(!$response['ok']||!$response['items']){http_response_code(503);exit('La oferta de Neuria no está disponible.');}$source=$response['items'][0];$record=['neuria_id'=>$neuriaId,'origen'=>'neuria','titulo'=>$source['titulo'],'bajada'=>$source['bajada'],'contenido'=>$source['contenido'],'volanta'=>'','seccion'=>$source['tipo'],'youtube_codigo'=>'','estado'=>'pendiente','publicacion_at'=>''];$isOffer=true;}
$date='';$time='';if(!empty($record['publicacion_at'])){$published=new DateTime($record['publicacion_at']);$date=$published->format('Y-m-d');$time=$published->format('H:i');}
$editorContent=($record['origen']??'')==='neuria'?neuria_texto_plano_editor((string)($record['contenido']??'')):(string)($record['contenido']??'');
?>
<div class="card admin-card mb-4"><div class="card-body p-4"><div class="d-flex justify-content-between"><div><h2 id="news-editor-title" class="h5 mb-1"><?=$isOffer?'Revisar oferta de Neuria':($id?'Editar noticia':'Nueva noticia')?></h2><p class="small text-secondary mb-0"><?=$isOffer?'Al guardarla se copiará a la base local con estado Pendiente.':'Primero guardá el texto; después cargá imágenes, video y documentos en sus paneles.'?></p></div><button class="btn-close" onclick="$('#news-panel').empty()" aria-label="Cerrar"></button></div>
<h3 class="h6 mt-4">1. Contenido de la nota</h3><div id="news-save-result" role="status" aria-live="polite"></div><form id="news-form" class="row g-3 mt-1"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="neuria_id" value="<?=(int)($record['neuria_id']??0)?>">
<div class="col-md-6"><label class="form-label">Volanta</label><input class="form-control" name="volanta" maxlength="160" value="<?=app_escape($record['volanta']??'')?>"></div><div class="col-md-6"><label class="form-label">Sección</label><input class="form-control" name="seccion" maxlength="120" value="<?=app_escape($record['seccion']??'')?>"></div>
<div class="col-12"><label class="form-label required">Título</label><input class="form-control" name="titulo" maxlength="240" required value="<?=app_escape($record['titulo']??'')?>"></div><div class="col-12"><label class="form-label">Bajada</label><textarea class="form-control" name="bajada" rows="3" maxlength="600"><?=app_escape($record['bajada']??'')?></textarea></div><div class="col-12"><label class="form-label required">Texto completo</label><textarea class="form-control" name="contenido" rows="12" required><?=app_escape($editorContent)?></textarea><div class="form-text"><?=($record['origen']??'')==='neuria'?'Texto plano: dejá una línea en blanco entre párrafos.':'Admite texto y HTML editorial básico; el sistema elimina código inseguro.'?></div></div>
<div class="col-md-3"><label class="form-label">Fecha de publicación</label><input class="form-control" type="date" name="fecha_publicacion" value="<?=app_escape($date)?>"></div><div class="col-md-3"><label class="form-label">Hora</label><input class="form-control" type="time" name="hora_publicacion" value="<?=app_escape($time)?>"></div><div class="col-md-3"><label class="form-label">Estado</label><select class="form-select" name="estado" <?=$isOffer?'disabled':''?>><?php foreach(['pendiente'=>'Pendiente','activa'=>'Activa','suspendida'=>'Suspendida'] as $value=>$label):?><option value="<?=$value?>" <?=($record['estado']??'pendiente')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select><?php if($isOffer):?><input type="hidden" name="estado" value="pendiente"><?php endif;?></div>
<div class="col-12 d-flex justify-content-end gap-2"><button class="btn btn-light" type="button" onclick="$('#news-panel').empty()">Cerrar editor</button><button class="btn btn-primary" type="submit">Guardar texto</button></div></form><hr class="my-4"><div id="news-attachments-panel"><?php if ($id): $noticiaAdjuntosId=$id; require __DIR__.'/app_adjuntos.php'; else: ?><div class="alert alert-light border mb-0"><i class="bi bi-lock me-2"></i>Guardá primero el texto de la nota para habilitar la carga de imágenes, video de YouTube y archivos descargables.</div><?php endif; ?></div><div class="text-end mt-3"><button type="button" class="btn btn-outline-secondary" onclick="newsReload()">Volver al listado actualizado</button></div></div></div>
<script src="modulos/noticias/js/editor.js"></script>
